fun {p} [Fact (Nat.Prime p)] {G₁} [Group G₁] [PrimeOrderWith G₁ p] [DecidableEq G₁] {G₂} {n L} hn tr i₁ i₂ =>
  have S := KZG.CommitmentScheme.chooseSConflict (tr.queryOf i₁) tr.srs hn;
  have Zₛ := ∏ s ∈ S, (CompPoly.CPolynomial.X - CompPoly.CPolynomial.C s);
  have h₁ := KZG.commit tr.srs.1 (Zₛ.coeff ∘ Fin.val);
  have h₂ := (tr.proofs i₁ / tr.proofs i₂) ^ (1 / (tr.responseOf i₂ - tr.responseOf i₁)).val;
  { support := S ∪ {tr.queryOf i₁}, base := h₁, solution := h₂ }

fun {p} [Fact (Nat.Prime p)] {G₁} [Group G₁] {G₂} n α srs =>
  have S := KZG.CommitmentScheme.chooseSMiddle n α;
  have Zₛ := ∏ s ∈ S, (CompPoly.CPolynomial.X - CompPoly.CPolynomial.C s);
  { support := S, base := srs.1[0], solution := srs.1[0] ^ (1 / CompPoly.CPolynomial.eval α Zₛ).val }

fun {p} [Fact (Nat.Prime p)] {L} U n query response =>
  have candidateslist := List.sublistsLen (n + 1) (U.sort fun x1 x2 => x1 ≤ x2);
  have candidates := List.map List.toFinset candidateslist;
  List.find? (fun s => decide (((CompPoly.CPolynomial.CLagrange.interpolate s query) response).degree = ↑n)) candidates

fun {p} [Fact (Nat.Prime p)] {G₁} [Group G₁] [PrimeOrderWith G₁ p] {G₂} {n L} S tr =>
  have Zₛ := ∏ s ∈ Finset.image tr.queryOf S, (CompPoly.CPolynomial.X - CompPoly.CPolynomial.C s);
  have c' :=
    KZG.commit tr.srs.1 ((↑((CompPoly.CPolynomial.CLagrange.interpolate S tr.queryOf) tr.responseOf)).coeff ∘ Fin.val);
  have h₁ := tr.cm / c';
  have d := fun α =>
    1 / CompPoly.CPolynomial.eval α (Zₛ.divByMonic (CompPoly.CPolynomial.X - CompPoly.CPolynomial.C α));
  have h₂ := ∏ i ∈ S, tr.proofs i ^ (d (tr.queryOf i)).val;
  { support := Finset.image tr.queryOf S, base := h₁, solution := h₂ }

