fun {p} [Fact (Nat.Prime p)] {G₁} [Group G₁] [DecidableEq G₁] {G₂} {n} αᵢ srs hn =>
  have arr :=
    Array.filterMap
      (fun i =>
        if h : i < p then
          have x := ↑↑⟨i, h⟩;
          if srs.1[0] ^ x.val ≠ srs.1[1] ∧ x ≠ αᵢ then some x else none
        else none)
      (Array.range p);
  (arr.take n).toList.toFinset

fun {p} [Fact (Nat.Prime p)] n α =>
